        [Handler(MethodId.CheckVersion)]
        public static void CheckVersion(Connection conn,UxRpcMessage msg)
        {
            RPCMethodArgsCheckVersion args = msg.GetArgs<RPCMethodArgsCheckVersion>();
            Console.WriteLine(args.clientVersion + " " + args.codeMd5);

            RPCMethodArgsCheckVersion conf = new() { clientVersion=args.clientVersion};
            UxRpcMessage rsp = new UxRpcMessage()
            {
                Mode=UxRpcPacketMode.Return,
                RpcInvokeId=msg.RpcInvokeId,
                RpcMethodId= msg.RpcMethodId,
                Args = new byte[0]{}
            };
            //rsp.SetArgs(msg.RpcMethodId,conf);
            conn.SendPacket(rsp);
        }
        public static string getToken()
        {
            static string Base64UrlEncode(string json)
            {
                return Convert.ToBase64String(Encoding.UTF8.GetBytes(json))
                    .TrimEnd('=')
                    .Replace('+', '-')
                    .Replace('/', '_');
            }

            long iat = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            long exp = iat + 3600; 

            string headerJson = "{\"alg\":\"none\",\"typ\":\"JWT\"}";

            string payloadJson =
                "{" +
                $"\"iat\":{iat}," +
                $"\"exp\":{exp}," +
                "\"sub\":\"aibgr4rznwj5r6zg@netease.win.163.com:netease:pc\"," +
                "\"gameid\":\"l50\"," +
                "\"typ\":1" +
                "}";

            string headerB64 = Base64UrlEncode(headerJson);
            string payloadB64 = Base64UrlEncode(payloadJson);

            string jwt = $"{headerB64}.{payloadB64}.";
            return jwt;
        }
