        [Handler(MethodId.TryLogin)]
        public static void TryLogin(Connection conn, UxRpcMessage msg)
        {
            RPCMethodArgsTryLogin args = msg.GetArgs<RPCMethodArgsTryLogin>();
            Console.WriteLine($"{args.ToString()}"); 

            UxRpcMessage rsp = new UxRpcMessage()
            {
                Mode = UxRpcPacketMode.Return,
                RpcInvokeId = msg.RpcInvokeId,
                RpcMethodId = (int)MethodId.TryLogin,
                RpcRetcode= (int)UxMessageRetcode.Ok
            };
            

            UxRpcMessage rsp1 = new UxRpcMessage()
            {
                Mode = UxRpcPacketMode.Notify,
                RpcInvokeId = msg.RpcInvokeId,
                RpcRetcode = 0,
                RpcMethodId = (int)35212978,
            };
            rsp1.SetArgs(MethodId.SyncRoleList, new RPCMethodArgs35212978() { roleId=1000000});
            conn.SendPacket(rsp1);
            UxRpcMessage rsp2 = new UxRpcMessage()
            {
                Mode = UxRpcPacketMode.Notify,
                RpcInvokeId = msg.RpcInvokeId,
                RpcRetcode = 0,
                RpcMethodId = (int)MethodId.SyncClientConfig,
            };
            rsp2.SetArgs(MethodId.SyncClientConfig, new RPCMethodArgsSyncClientConfig());
            conn.SendPacket(rsp2);
            UxRpcMessage rsp3 = new UxRpcMessage()
            {
                Mode = UxRpcPacketMode.Notify,
                RpcInvokeId = msg.RpcInvokeId,
                RpcRetcode = 0,
                RpcMethodId = (int)MethodId.SyncGameSwitchToClient,
                Args = new byte[4] { 0x00, 0x00, 0x00, 0x00 } //UID?
            };
            rsp3.SetArgs(MethodId.SyncGameSwitchToClient, new SyncGameSwitchToClient());
          //  conn.SendPacket(rsp3);
            UxRpcMessage rsp4 = new UxRpcMessage()
            {
                Mode = UxRpcPacketMode.Notify,
                RpcInvokeId = msg.RpcInvokeId,
                RpcRetcode = 0,
                RpcMethodId = (int)35056687,
                Args = new byte[4] { 0x00, 0x00, 0x00, 0x00 } //UID?
            };
            conn.SendPacket(rsp4);

            conn.SendPacket(rsp);
            // conn.Disconnect();
        }
